#!/usr/bin/env python3
"""Hourly station product from logger dumps (see /app/docs)."""
import calendar
import json
import math
import os
import re
import sys

QUANTITIES = ("temp", "rh", "pres", "wspd", "wdir", "rain")
RANGES = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
          "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
MISSING_RE = re.compile(r"^-9999(\.0*)?$")
DIRECTIVE_RE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
TIME_RE = re.compile(r"^(\d{4})-(\d\d)-(\d\d)[ T](\d\d):(\d\d):(\d\d)$")


def parse_time(s):
    m = TIME_RE.match(s.strip())
    y, mo, d, h, mi, se = map(int, m.groups())
    return calendar.timegm((y, mo, d, h, mi, se, 0, 0, 0))


def parse_tz(s):
    s = s.strip()
    if s == "Z":
        return 0
    sign = -1 if s[0] == "-" else 1
    hh, mm = s[1:].split(":")
    return sign * (int(hh) * 3600 + int(mm) * 60)


def convert(q, unit, v):
    if q == "temp":
        if unit == "degF":
            return (v - 32) * 5 / 9
        if unit == "K":
            return v - 273.15
    elif q == "rh":
        if unit == "frac":
            return v * 100
    elif q == "pres":
        if unit == "kPa":
            return v * 10
        if unit == "inHg":
            return v * 33.8638866667
        if unit == "mmHg":
            return v * 1.33322387415
    elif q == "wspd":
        if unit == "kmh":
            return v / 3.6
        if unit == "kn":
            return v * 1852 / 3600
        if unit == "mph":
            return v * 0.44704
    elif q == "rain":
        if unit.startswith("tips:"):
            return v * float(unit[5:])
    return v


def is_missing(f):
    return f == "" or MISSING_RE.match(f) is not None or f.lower() == "nan" or f == "---"


def read_file(path):
    with open(path, "rb") as fh:
        text = fh.read().decode("utf-8-sig")
    hdr = {}
    columns = None
    units = {}
    rows = []   # (logger_time_epoch, {q: value})
    syncs = []  # (logger_time_epoch, ref_epoch)
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line[0] == "#":
            m = DIRECTIVE_RE.match(line)
            if not m:
                continue
            key, val = m.group(1), m.group(2).strip()
            if key in ("station", "upload", "interval", "tz"):
                hdr[key] = val
            elif key == "columns":
                columns = [c.strip() for c in val.split(",")]
                if "columns" not in hdr:
                    hdr["columns"] = True
            elif key == "units":
                for pair in val.split():
                    if "=" in pair:
                        k, u = pair.split("=", 1)
                        units[k] = u
            elif key == "sync":
                parts = {}
                for p in val.split():
                    if "=" in p:
                        k, v = p.split("=", 1)
                        parts[k] = v
                if "logger" in parts and "ref" in parts:
                    syncs.append((parse_time(parts["logger"]),
                                  parse_time(parts["ref"].rstrip("Z"))))
            continue
        fields = [f.strip() for f in line.split(",")]
        vals = {}
        t = None
        for name, f in zip(columns, fields):
            if name == "time":
                t = parse_time(f)
                continue
            if name not in RANGES or is_missing(f):
                continue
            try:
                v = float(f)
            except ValueError:
                continue
            if math.isnan(v):
                continue
            v = convert(name, units.get(name, ""), v)
            lo, hi = RANGES[name]
            if lo <= v <= hi:
                vals[name] = v
        rows.append((t, vals))
    return hdr, rows, syncs


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p):
            continue
        hdr, rows, syncs = read_file(p)
        if "station" not in hdr:
            continue
        tz = parse_tz(hdr.get("tz", "Z"))
        upload = int(hdr.get("upload", 0))
        st = stations.setdefault(hdr["station"], {"interval": None, "rows": {}, "syncs": {}})
        if rows and "interval" in hdr:
            st["interval"] = int(float(hdr["interval"]))
        for t, vals in rows:
            u = t - tz
            old = st["rows"].get(u)
            if old is None or upload > old[0]:
                st["rows"][u] = (upload, vals)
        for lt, ref in syncs:
            u = lt - tz
            old = st["syncs"].get(u)
            if old is None or upload > old[0]:
                st["syncs"][u] = (upload, ref - u)

    result = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        interval = st["interval"] or 0
        pts = sorted((u, o) for u, (_, o) in st["syncs"].items())

        def offset(t):
            if not pts:
                return 0
            if t <= pts[0][0]:
                return pts[0][1]
            if t >= pts[-1][0]:
                return pts[-1][1]
            lo, hi = 0, len(pts) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if pts[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            (t1, o1), (t2, o2) = pts[lo], pts[hi]
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)

        recs = []
        for u, (_, vals) in st["rows"].items():
            recs.append((u + offset(u), u, vals))
        recs.sort(key=lambda r: (r[0], r[1]))

        hours = {}

        def hour_of(c):
            return -((-c) // 3600) * 3600

        for c, u, vals in recs:
            h = hours.setdefault(hour_of(c), {"vals": {q: [] for q in QUANTITIES},
                                              "vec": [0.0, 0.0], "nvec": 0, "inc": []})
            for q, v in vals.items():
                h["vals"][q].append(v)
            if "wdir" in vals and vals.get("wspd", 0) > 0:
                a = math.radians(vals["wdir"])
                h["vec"][0] += math.sin(a)
                h["vec"][1] += math.cos(a)
                h["nvec"] += 1

        prev = None
        for c, u, vals in recs:
            if "rain" not in vals:
                continue
            r = vals["rain"]
            if prev is not None and (c - prev[0]) * 2 <= 5 * interval:
                inc = r - prev[1] if r >= prev[1] else r
                hours[hour_of(c)]["inc"].append(inc)
            prev = (c, r)

        first, last = min(hours), max(hours)
        out_hours = []
        hh = first
        while hh <= last:
            h = hours.get(hh)
            ts = "%04d-%02d-%02dT%02d:00:00Z" % tuple(__import__("time").gmtime(hh)[:4])
            entry = {"hour": ts}
            for q in QUANTITIES:
                n = len(h["vals"][q]) if h else 0
                val = None
                expected = 3600 / interval if interval else 0
                if h and n > 0 and n * 4 * interval >= 3600 * 3:
                    xs = h["vals"][q]
                    if q in ("temp", "rh", "pres", "wspd"):
                        val = math.fsum(xs) / n
                    elif q == "wdir":
                        if h["nvec"] and (h["vec"][0] or h["vec"][1]):
                            val = math.degrees(math.atan2(h["vec"][0], h["vec"][1])) % 360
                    else:
                        val = math.fsum(h["inc"])
                if val is not None:
                    val = round(val, 2)
                    if val >= 360 and q == "wdir":
                        val = 0.0
                    if val == 0:
                        val = abs(val)
                entry[q] = {"value": val, "n": n}
            out_hours.append(entry)
            hh += 3600
        result.append({"station": sid, "interval_s": interval, "hours": out_hours})

    with open(outfile, "w", encoding="utf-8") as fh:
        json.dump({"stations": result}, fh)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
